mapper.select:
SELECT COALESCE(SUM(amount), 0)
FROM fee_expense_bill
WHERE dept_id = #{deptId}
  AND calc_budget_subject = #{budgetSubjectCode}
  AND status = 'APPROVED'

mapper.update:
UPDATE fee_expense_bill
SET status = #{status}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT e.calc_budget_subject AS budgetSubjectCode, bs.subject_name AS budgetSubjectName, e.calc_accounting_class AS accountingClass, SUM(e.amount) AS actualAmount, COALESCE(bd.budget_amount, 0) AS budgetAmount, COALESCE(bd.budget_amount, 0) - SUM(e.amount) AS varianceAmount FROM fee_expense_bill e LEFT JOIN budget_subject bs ON e.calc_budget_subject = bs.subject_code LEFT JOIN budget_preparation_detail bd ON bd.subject_code = e.calc_budget_subject AND bd.dept_id = e.dept_id AND YEAR(bd.create_time) = #{year} AND MONTH(bd.create_time) = #{month} WHERE e.status = 'APPROVED'
AND YEAR(e.expense_date) = #{year}
AND MONTH(e.expense_date) = #{month}
AND e.dept_id = #{orgId}
GROUP BY e.calc_budget_subject, e.calc_accounting_class ORDER BY e.calc_accounting_class, e.calc_budget_subject
